entries[251915] = { ["name"] = "Sengende Rune", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine sengende Rune erscheint auf dem Boden. Durch den Aufenthalt in ihrem Effektbereich erleiden Spielercharaktere alle 1 Sek. 56 Feuerschaden und werden mit ' Sengende Macht ' belegt. Weitere Anwendungen von ' Sengende Macht ' erhöhen zwar die Dauer, aber nicht die Wirksamkeit des Effekts." }
