entries[251919] = { ["name"] = "Sengende Runen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSengende Runen erscheinen regelmäßig auf dem Boden. Durch den Aufenthalt im Effektbereich einer sengenden Rune erleiden Spielercharaktere Schaden, ihre Macht erhöht sich jedoch für kurze Zeit." }
